        <title>{name}</title>
        <g>{mark}</g>
        <text
          dominantBaseline="central"
          fontFamily="inherit"
          fontSize="17"
          fontWeight="600"
          letterSpacing="-0.4"
          x="33"
          y="20.5"
        >
          {name}
        </text>
      </svg>
    );
  };

